const generated=ref<any>(),previewSource=ref('live'),generatedChapter=computed(()=>generated.value?.chapters.find((c:ManualChapter)=>c.id===chapterId.value)),previewChapter=computed(()=>previewSource.value==='generated'?generatedChapter.value:current.value),previewAssets=computed(()=>previewSource.value==='generated'?generated.value?.project.assets??[]:project.value?.assets??[]),previewReferences=computed(()=>previewSource.value==='generated'?generated.value?.project.references??[]:project.value?.references??[]),previewAssetUrl=(asset:ManualAsset)=>previewSource.value==='generated'?readingAssetUrl(asset,generated.value?.distribution??'software'):assetUrl(asset);
const preview=ref(true),dark=ref(false),previewWidth=ref('auto'),sourceVisible=ref(false),sourceDraft=ref(''),inspector=ref('block'),inspectorOpen=ref(false),selected=ref<{type:string;attrs:Record<string,any>;pos:number}>(),recoveryItems=ref<any[]>([]),recoveryVisible=ref(false),mediaInput=ref<HTMLInputElement>(),importInput=ref<HTMLInputElement>(),formatRevision=ref(0),searchText=ref(''),replaceText=ref(''),autoSave=ref(true),selectedAssetId=ref('');
const askText=window.prompt.bind(window);
