let stopPageLifetime:(()=>void)|undefined;
const clone=<T,>(value:T):T=>JSON.parse(JSON.stringify(value));
const newId=(prefix:string)=>prefix+'-'+crypto.randomUUID();
const emptyDoc=():ManualNode=>({type:'doc',content:[{type:'paragraph'}]});
const arrangeUndo:Snapshot[]=[];
function arrangeHistory(){if(snapshot.value){arrangeUndo.push(clone(snapshot.value));if(arrangeUndo.length>60)arrangeUndo.shift();}}
function editorStorage(){if(editor.value)(editor.value.storage as any).manualAssets={assets:project.value?.assets??[],resolve:assetUrl};}
function selectedState(){if(!editor.value)return;formatRevision.value++;const sel=editor.value.state.selection,node=sel instanceof NodeSelection?sel.node:sel.$from.parent,pos=sel instanceof NodeSelection?sel.from:(sel.$from.depth>0?sel.$from.before(sel.$from.depth):0);selected.value={type:sourceNodeType(node.type.name),attrs:clone(node.attrs),pos};}
function collectSections(chapter:ManualChapter){const sections:any[]=[];const walk=(node:ManualNode)=>{if(node.type==='heading'&&node.attrs?.id)sections.push({id:node.attrs.id,title:(node.content??[]).map(c=>c.text??'').join(''),level:node.attrs.level??2});for(const child of node.content??[])walk(child);};walk(chapter.body);return sections;}
function syncEditor(){if(current.value&&editor.value&&!unsupported.value.length){current.value.body=fromEditorDocument(editor.value.getJSON()) as ManualNode;const descriptor=chapterDescriptor.value;if(descriptor)descriptor.sections=collectSections(current.value);}}
