  const instance=new Editor({extensions:extensions(project.value?.assets??[],assetUrl),content:toEditorDocument(clone(current.value.body) as JSONContent),editorProps:{attributes:{'aria-label':'章节正文','lang':'zh-CN'},handlePaste(_view,event){const file=[...(event.clipboardData?.files??[])].find(f=>f.type.startsWith('image/'));if(file){event.preventDefault();void importMedia(file,'image');return true;}return false;},handleDrop(_view,event){const file=event.dataTransfer?.files[0];if(file&&/^(image|audio|video)\//.test(file.type)){event.preventDefault();void importMedia(file,file.type.split('/')[0]);return true;}return false;}},onUpdate(){syncEditor();markDirty();selectedState();},onSelectionUpdate(){selectedState();},onTransaction(){formatRevision.value++;}});
