function applySnapshot(value:Snapshot){clearTimeout(autoTimer);clearTimeout(draftTimer);projectGeneration++;generated.value=undefined;previewSource.value='live';snapshot.value=value;pathInput.value=value.path;chapterId.value=value.project.chapters.some(c=>c.id===chapterId.value)?chapterId.value:value.project.chapters[0]?.id??'';dirty.value=false;error.value='';status.value='磁盘内容已读取';lastSaved.value=new Date().toLocaleTimeString('zh-CN');arrangeUndo.splice(0);createEditor();}
async function run(action:()=>Promise<any>){error.value='';try{return await action();}catch(e:any){error.value=e.message;status.value='操作未完成';return null;}}
async function openProject(create=false){if(dirty.value&&!await save())return;const value=await run(()=>api(create?'create':'open',{path:pathInput.value,title:titleInput.value}));if(value)applySnapshot(value);}
let savePromise:Promise<boolean>|undefined;
async function save():Promise<boolean>{if(savePromise){const okay=await savePromise;if(!okay)return false;return dirty.value?save():true;}savePromise=performSave().finally(()=>{savePromise=undefined;});return savePromise;}
async function performSave(){if(!snapshot.value)return false;clearTimeout(autoTimer);clearTimeout(draftTimer);saving.value=true;status.value='正在保存到磁盘…';
  const generation=projectGeneration,document=payload(),fingerprint=JSON.stringify(document);try{const result=await api('save',document);if(generation!==projectGeneration)return false;snapshot.value.revision=result.revision;if(editor.value)editor.value.view.dispatch(closeHistory(editor.value.state.tr));lastSaved.value=new Date().toLocaleTimeString('zh-CN');const latest=payload();latest.baseRevision=document.baseRevision;dirty.value=JSON.stringify(latest)!==fingerprint;status.value=dirty.value?'磁盘已保存，仍有新的编辑':'已保存到磁盘 · '+lastSaved.value;if(dirty.value&&autoSave.value)autoTimer=setTimeout(()=>void save(),1200);return true;}catch(e:any){error.value=e.message;status.value=e.status===409?'存在外部修改 · 当前稿已存为恢复稿':'保存失败 · 当前编辑仍保留';return false;}finally{saving.value=false;}}
async function selectChapter(id:string){if(id===chapterId.value)return;if(dirty.value&&!await save())return;syncEditor();chapterId.value=id;createEditor();}
function ensureChapter(){if(!project.value||!snapshot.value)return;arrangeHistory();const id=newId('chapter'),chapter:ManualChapter={schemaVersion:'ptb-manual-chapter/1',id,title:'新章节',body:emptyDoc()};project.value.chapters.push({id,title:chapter.title,path:`chapters/${id}.json`,status:'draft'});snapshot.value.chapters.push(chapter);chapterId.value=id;createEditor();markDirty();}
function renameChapter(){if(current.value&&chapterDescriptor.value){chapterDescriptor.value.title=current.value.title;markDirty();}}
function reorder(direction:number){if(!project.value)return;const index=project.value.chapters.findIndex(c=>c.id===chapterId.value),target=index+direction;if(target<0||target>=project.value.chapters.length)return;arrangeHistory();const [item]=project.value.chapters.splice(index,1);project.value.chapters.splice(target,0,item);markDirty();}
function duplicateChapter(){if(!current.value||!snapshot.value||!project.value)return;syncEditor();arrangeHistory();const id=newId('chapter'),chapter=clone(current.value);chapter.id=id;chapter.title+='（副本）';const renew=(node:ManualNode)=>{if(node.attrs?.id)node.attrs.id=newId(node.type);for(const child of node.content??[])renew(child);};renew(chapter.body);snapshot.value.chapters.push(chapter);const index=project.value.chapters.findIndex(c=>c.id===chapterId.value);project.value.chapters.splice(index+1,0,{id,title:chapter.title,path:`chapters/${id}.json`,moduleId:chapter.moduleId,status:'draft'});chapterId.value=id;createEditor();markDirty();}
function removeChapter(){if(!current.value||!project.value||!snapshot.value)return;if(!confirm('从目录撤下此章节？正文文件和素材会保留在工程中，可以通过撤销编排恢复。'))return;arrangeHistory();const index=project.value.chapters.findIndex(c=>c.id===chapterId.value);project.value.chapters.splice(index,1);snapshot.value.chapters=snapshot.value.chapters.filter(c=>c.id!==chapterId.value);chapterId.value=project.value.chapters[Math.min(index,project.value.chapters.length-1)]?.id??'';createEditor();markDirty();}
