function insertLink(){const href=prompt('链接地址（HTTP(S)、mailto）',editor.value?.getAttributes('link').href??'https://');if(href==null)return;if(!/^(https?:\/\/|mailto:)/i.test(href)){error.value='请输入有效的 HTTP(S) 或 mailto 链接';return;}command('setLink',{href});}
