function addReference(){const id=newId('ref');project.value?.references?.push({id,label:'作者（年份）',url:''});openInspector('references');markDirty();}
function insertReference(){const reference=project.value?.references?.[0];if(!reference){addReference();return;}insertNode('citation',{referenceId:reference.id,label:reference.label});}
