async function importMedia(file:File,kind:string){if(!snapshot.value)return;try{if(dirty.value&&!await save())return;const result=await api('asset',{baseRevision:snapshot.value.revision,name:file.name,data:await fileBase64(file),kind,distribution:'software-only',sourceType:kind==='audio'?'未分类':'作者导入',source:''});snapshot.value.revision=result.snapshot.revision;snapshot.value.project.assets=result.snapshot.project.assets;Object.assign(snapshot.value.project.assets.find(a=>a.id===result.asset.id)!,await mediaMetadata(file,kind));editorStorage();insertNode(kind,{assetId:result.asset.id,caption:'',alt:kind==='image'?file.name:'',width:kind==='image'?'100%':null});selectedAssetId.value=result.asset.id;openInspector('assets');}catch(e:any){error.value=e.message;}}
function mediaPicked(event:Event){const file=(event.target as HTMLInputElement).files?.[0];if(file){let kind=/^image\//.test(file.type)?'image':/^audio\//.test(file.type)?'audio':/^video\//.test(file.type)?'video':'';if(!kind)kind=/\.(wav|mp3|flac|ogg|m4a)$/i.test(file.name)?'audio':/\.(mp4|webm|mov)$/i.test(file.name)?'video':'image';void importMedia(file,kind);}(event.target as HTMLInputElement).value='';}
async function exportProject(mode='software'){if(dirty.value&&!await save())return;await run(async()=>{const skipped=await bundleExport(mode);status.value=mode==='public'?`公开内容包已导出，跳过 ${skipped} 份受限素材`:'完整工程包已导出，含正文与全部工程素材';});}
async function importProject(event:Event){const file=(event.target as HTMLInputElement).files?.[0];if(!file)return;const target=prompt('把工程包导入到新的空目录（绝对路径）');if(target){const value=await run(()=>fileBase64(file).then(data=>api('import',{path:target,data})));if(value)applySnapshot(value);}(event.target as HTMLInputElement).value='';}
async function buildReading(){if(dirty.value&&!await save())return;await run(async()=>{const result=await api('build',{});generated.value=result;previewSource.value='generated';status.value='阅读资源已生成：'+result.path;});}
async function showRecovery(){const items=await run(()=>api('recovery'));if(items){recoveryItems.value=items;recoveryVisible.value=true;}}
async function loadRecovery(id:string){if(dirty.value&&!confirm('加载恢复稿会替换当前页面内容。当前稿可先保存或导出。继续？'))return;const value=await run(()=>api('recovery/'+id));if(value&&snapshot.value){arrangeHistory();snapshot.value.project=value.project;snapshot.value.chapters=value.chapters;chapterId.value=value.project.chapters[0]?.id??'';createEditor();markDirty();recoveryVisible.value=false;status.value='恢复稿已载入，请检查后保存';}}
function showSource(){syncEditor();sourceDraft.value=JSON.stringify(current.value,null,2);sourceVisible.value=true;}
async function applySource(){try{const chapter=JSON.parse(sourceDraft.value);if(chapter.id!==chapterId.value||chapter.schemaVersion!=='ptb-manual-chapter/1'||chapter.body?.type!=='doc')throw new Error('章节版本、ID 或正文结构无效');const unknown=unknownTypes(chapter.body);if(unknown.length)throw new Error('尚不支持的节点：'+unknown.join('、'));const candidate=clone(payload());candidate.chapters=candidate.chapters.map((c:ManualChapter)=>c.id===chapter.id?chapter:c);candidate.project!.chapters=candidate.project!.chapters.map((d:any)=>d.id===chapter.id?{...d,title:chapter.title}:d);await api('draft',candidate);const index=snapshot.value!.chapters.findIndex(c=>c.id===chapter.id);snapshot.value!.chapters[index]=chapter;chapterDescriptor.value!.title=chapter.title;createEditor();markDirty();sourceVisible.value=false;}catch(e:any){error.value='结构没有应用：'+e.message;}}
function sourceDownload(){const blob=new Blob([JSON.stringify(current.value,null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=chapterId.value+'.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
async function navigate(target:ManualTarget){if(target.chapterId!==chapterId.value)await selectChapter(target.chapterId);await nextTick();if(target.targetId)document.querySelector('.reading-preview [id="'+CSS.escape(target.targetId)+'"]')?.scrollIntoView({block:'center'});}
function blockMove(direction:number){if(!editor.value)return;const selection=editor.value.state.selection,index=selection.$from.index(0),body=editor.value.getJSON(),nodes=body.content??[],target=index+direction;if(target<0||target>=nodes.length)return;const item=nodes.splice(index,1)[0];nodes.splice(target,0,item);editor.value.commands.setContent(body,{emitUpdate:true});}
function keyboard(event:KeyboardEvent){if((event.ctrlKey||event.metaKey)&&event.key.toLowerCase()==='s'){event.preventDefault();void save();}}
function beforeUnload(event:BeforeUnloadEvent){if(dirty.value){event.preventDefault();event.returnValue='';}}
async function closeTool(){if(dirty.value&&!await save())return;await run(async()=>{await api('close',{});stopPageLifetime?.();clearTimeout(autoTimer);clearTimeout(draftTimer);status.value='作者工具已退出，可以关闭此页面。';editor.value?.setEditable(false,false);});}
