onMounted(async()=>{window.addEventListener('keydown',keyboard);window.addEventListener('beforeunload',beforeUnload);stopPageLifetime=bindPageLifetime(message=>{error.value=message;});const result=await run(()=>api('session'));if(result?.snapshot)applySnapshot(result.snapshot);});
