const buttons=[['toggleBold','粗体','B'],['toggleItalic','斜体','I'],['toggleUnderline','下划线','U'],['toggleStrike','删除线','S'],['toggleSubscript','下标','x₂'],['toggleSuperscript','上标','x²'],['toggleCode','行内代码','<>'],['toggleMark','IPA 样式','IPA']] as const;
const isActive=(name:string)=>{formatRevision.value;const mapped:{[key:string]:string}={toggleBold:'bold',toggleItalic:'italic',toggleUnderline:'underline',toggleStrike:'strike',toggleSubscript:'subscript',toggleSuperscript:'superscript',toggleCode:'code',toggleMark:'ipa'};return !!editor.value?.isActive(mapped[name]??name);};
const inputValue=(event:Event)=>(event.target as HTMLInputElement).value;
</script>

<template>
  <main class="studio">
    <header class="studio-header"><div class="brand"><span class="brand-mark">文</span><div><strong>说明书作者工作室</strong><small>PHONETICTOOLBOX · MANUAL STUDIO</small></div></div><span class="save-state" :class="{dirty}">{{ status }}</span><div class="header-actions"><button @click="dark=!dark">{{ dark?'浅色':'深色' }}</button><button @click="preview=!preview">{{ preview?'收起预览':'正式预览' }}</button><button :disabled="!snapshot" :class="{active:inspectorOpen}" :aria-expanded="inspectorOpen" aria-controls="editor-inspector" aria-label="排版、素材与文献" title="排版、素材与文献" @mousedown.prevent @click="inspectorOpen=!inspectorOpen">编辑工具</button><button :disabled="!snapshot||saving" class="primary" @click="save">保存 Ctrl+S</button><button @click="closeTool">退出工具</button></div></header>
    <div v-if="error" class="error-banner" role="alert">{{ error }}<button @click="error=''">收起</button></div>
    <section v-if="!snapshot" class="project-welcome"><span class="eyebrow">一份工程，持续写作</span><h1>打开你的说明书</h1><p>正文、图片和声音保存在工程目录中，阅读预览与软件内的正式说明书共用同一组件。</p><label>工程目录<input v-model="pathInput" placeholder="D:\PhoneticToolbox\PhoneticToolbox_v3\manual" aria-label="工程目录"></label><label>新工程标题<input v-model="titleInput" aria-label="新工程标题"></label><div><button class="primary" @click="openProject()">打开工程</button><button @click="openProject(true)">建立空工程</button><button @click="importInput?.click()">导入工程包</button></div><p class="muted">新建和导入须使用空目录，已有文件不会被覆盖。</p></section>
    <section v-else class="workspace" :class="{'preview-hidden':!preview,'inspector-open':inspectorOpen}">
      <aside class="chapter-sidebar"><div class="sidebar-title"><strong>章节目录</strong><button title="新建章节" aria-label="新建章节" @click="ensureChapter">＋</button></div><div class="project-caption">{{ project?.title }}</div><nav class="chapter-list"><button v-for="(item,index) in project?.chapters" :key="item.id" :class="{selected:item.id===chapterId}" @click="selectChapter(item.id)"><span>{{ String(index+1).padStart(2,'0') }}</span><div>{{ item.title }}<small>{{ item.moduleId || '公共章节' }} · {{ item.status || 'draft' }}</small></div></button></nav><div class="chapter-actions"><button @click="reorder(-1)">上移</button><button @click="reorder(1)">下移</button><button @click="duplicateChapter">复制</button><button @click="removeChapter">撤下</button><button @click="splitChapter">拆分</button><button @click="mergeNext">合并下一章</button><button class="wide" @click="undoArrangement">撤销编排</button></div><details class="engineering" open><summary>工程管理</summary><button @click="showRecovery">磁盘恢复稿</button><button @click="exportProject()">导出完整工程</button><button @click="exportProject('public')">导出公开内容</button><button @click="importInput?.click()">导入工程包</button><button @click="buildReading">生成阅读资源</button><button @click="openProject()">重新读取磁盘</button><label><input v-model="autoSave" type="checkbox"> 自动保存到磁盘</label><input v-model="pathInput" aria-label="切换工程目录"><button @click="openProject()">切换工程</button><small class="project-path">{{ snapshot.path }}</small></details></aside>
      <section class="author-pane"><div v-if="current" class="chapter-heading"><input v-model="current.title" aria-label="章节标题" @input="renameChapter"><div><input v-model="current.moduleId" aria-label="模块ID" placeholder="M08 / 公共章" @input="chapterDescriptor!.moduleId=current.moduleId;markDirty()"><select v-model="chapterDescriptor!.status" aria-label="章节状态" @change="markDirty"><option value="draft">草稿</option><option value="verified">已核验</option><option value="in_progress">修订中</option><option value="planned">预留</option></select><button @click="showSource">结构源码</button><button @click="sourceDownload">导出本章</button></div></div>
        <template v-if="current"><div v-if="unsupported.length" class="unknown-content"><h2>此章节含尚不支持的内容</h2><p>{{ unsupported.join('、') }}</p><p>原始 JSON 保持完整。请通过结构源码修订，或导出本章交给维护者处理。</p><button @click="showSource">打开结构源码</button><button @click="sourceDownload">导出原始章节</button></div>
        <template v-else><div class="toolbar" role="toolbar" aria-label="富文本工具栏"><div class="toolbar-row"><button title="撤销" aria-label="撤销" @mousedown.prevent @click="command('undo')">↶</button><button title="重做" aria-label="重做" @mousedown.prevent @click="command('redo')">↷</button><span class="separator"></span><select aria-label="段落类型" @change="inputValue($event)==='paragraph'?command('setParagraph'):command('toggleHeading',{level:Number(inputValue($event))})"><option value="paragraph">正文段落</option><option value="1">一级标题</option><option value="2">二级标题</option><option value="3">三级标题</option><option value="4">四级标题</option></select><button v-for="[name,label,symbol] in buttons" :key="name" :title="label" :aria-label="label" :class="{active:isActive(name)}" @mousedown.prevent @click="command(name,name==='toggleMark'?'ipa':undefined)">{{ symbol }}</button><button title="清除文字格式" @mousedown.prevent @click="command('unsetAllMarks')">清格式</button></div>
        <div class="toolbar-row"><select aria-label="字体" @change="command('setFontFamily',inputValue($event))"><option value="SimSun">宋体</option><option value="Microsoft YaHei">微软雅黑</option><option value="Times New Roman">Times</option><option value="JetBrains Mono">等宽</option><option value="Doulos SIL">Doulos SIL</option></select><select aria-label="字号" @change="command('setFontSize',inputValue($event))"><option value="16px">字号 16</option><option v-for="size in [10,12,14,18,20,24,28,32,40,48]" :key="size" :value="size+'px'">{{ size }} px</option></select><label class="color-tool" title="文字颜色">字色<input type="color" aria-label="文字颜色" @input="command('setColor',inputValue($event))"></label><label class="color-tool" title="背景强调">强调<input type="color" value="#fff1b0" aria-label="背景强调" @input="command('setHighlight',{color:inputValue($event)})"></label><span class="separator"></span><button v-for="[align,label] in [['left','左'],['center','中'],['right','右'],['justify','两端']]" :key="align" :aria-label="label+'对齐'" @mousedown.prevent @click="command('setTextAlign',align)">{{ label }}</button><button @mousedown.prevent @click="command('toggleBulletList')">• 列表</button><button @mousedown.prevent @click="command('toggleOrderedList')">1. 列表</button><button @mousedown.prevent @click="command('toggleBlockquote')">引用段</button></div>
        <div class="toolbar-row"><button @click="mediaInput?.click()">图 / 音频 / 视频</button><button @mousedown.prevent @click="command('insertTable',{rows:3,cols:3,withHeaderRow:true})">表格</button><button @mousedown.prevent @click="insertNode('formula',{latex:'f_0 = 1 / T',display:true})">公式</button><button @mousedown.prevent @click="command('toggleCodeBlock')">代码块</button><button @mousedown.prevent @click="insertLink">链接</button><button @mousedown.prevent @click="addCrossReference">交叉引用</button><button @mousedown.prevent @click="insertReference">文献</button><button @mousedown.prevent @click="addNote('footnote')">脚注</button><button @mousedown.prevent @click="addColumns">双栏</button><button @mousedown.prevent @click="addNote('admonition')">提示框</button><button @mousedown.prevent @click="command('setHorizontalRule')">分隔线</button></div></div>
        <div class="editing-area"><EditorContent :editor="editor" /></div></template></template><div v-else class="empty-editor"><h2>从第一章开始</h2><button class="primary" @click="ensureChapter">新建章节</button></div>
      </section>
      <aside v-if="inspectorOpen" id="editor-inspector" class="inspector-pane" aria-label="编辑工具栏"><div class="inspector-tabs"><button v-for="[key,label] in [['block','排版'],['assets','素材'],['references','文献']]" :key="key" :class="{active:inspector===key}" @click="inspector=key">{{ label }}</button><button class="inspector-close" aria-label="收起编辑工具" @click="inspectorOpen=false">收起</button></div>
        <section v-if="inspector==='block'" class="properties"><strong>{{ selected?.type || '段落' }} 属性</strong><template v-if="selected"><label>稳定锚点<input :value="selected.attrs.id || ''" @change="patchSelected('id',inputValue($event)||null)"></label><template v-if="['image','audio','video'].includes(selected.type)"><label>素材<select :value="selected.attrs.assetId" @change="patchSelected('assetId',inputValue($event))"><option v-for="asset in project?.assets.filter(a=>a.kind===selected!.type)" :key="asset.id" :value="asset.id">{{ asset.title||asset.id }}</option></select></label><label>标题 / 图注<textarea :value="selected.attrs.caption" @input="patchSelected('caption',inputValue($event))"></textarea></label><label>替代文字<input :value="selected.attrs.alt" @input="patchSelected('alt',inputValue($event))"></label><label>显示宽度<input :value="selected.attrs.width" placeholder="100% / 480px" @change="patchSelected('width',inputValue($event))"></label><label>对齐<select :value="selected.attrs.align" @change="patchSelected('align',inputValue($event))"><option value="left">左</option><option value="center">中</option><option value="right">右</option></select></label></template>
        <template v-if="selected.type==='formula'"><label>LaTeX 公式<textarea :value="selected.attrs.latex" @input="patchSelected('latex',inputValue($event))"></textarea></label></template>
        <template v-if="selected.type==='crossReference'"><label>章节<select :value="selected.attrs.chapterId" @change="patchSelected('chapterId',inputValue($event))"><option v-for="item in project?.chapters" :key="item.id" :value="item.id">{{ item.title }}</option></select></label><label>目标锚点<input :value="selected.attrs.targetId" @input="patchSelected('targetId',inputValue($event))"></label><label>显示文字<input :value="selected.attrs.label" @input="patchSelected('label',inputValue($event))"></label></template>
        <template v-if="selected.type==='citation'"><label>文献<select :value="selected.attrs.referenceId" @change="patchSelected('referenceId',inputValue($event))"><option v-for="item in project?.references" :key="item.id" :value="item.id">{{ item.label }}</option></select></label><label>引用文字<input :value="selected.attrs.label" @input="patchSelected('label',inputValue($event))"></label></template>
        <template v-if="['paragraph','heading','tableCell','tableHeader'].includes(selected.type)"><label>行距<input :value="selected.attrs.lineHeight || ''" placeholder="1.75" @change="patchSelected('lineHeight',inputValue($event)||null)"></label><label>段前<input :value="selected.attrs.marginTop || ''" placeholder="0.5em" @change="patchSelected('marginTop',inputValue($event)||null)"></label><label>段后<input :value="selected.attrs.marginBottom || ''" placeholder="0.75em" @change="patchSelected('marginBottom',inputValue($event)||null)"></label><label>缩进级数<input type="number" min="0" max="12" :value="selected.attrs.indent || 0" @change="patchSelected('indent',Number(inputValue($event)))"></label><label>底色<input type="color" :value="selected.attrs.backgroundColor || '#ffffff'" @input="patchSelected('backgroundColor',inputValue($event))"></label></template>
        <template v-if="selected.type==='codeBlock'"><label>代码语言<input :value="selected.attrs.language || ''" @input="patchSelected('language',inputValue($event))"></label></template>
        <template v-if="selected.type==='admonition'"><label>提示类别<select :value="selected.attrs.kind" @change="patchSelected('kind',inputValue($event))"><option value="tip">操作提示</option><option value="condition">条件说明</option><option value="result">结果解释</option><option value="limitation">限制</option></select></label></template>
        </template><details open><summary>表格操作</summary><div class="table-tools"><button v-for="[name,label] in [['addRowBefore','前加行'],['addRowAfter','后加行'],['deleteRow','删行'],['addColumnBefore','前加列'],['addColumnAfter','后加列'],['deleteColumn','删列'],['mergeCells','合并格'],['splitCell','拆分格'],['toggleHeaderRow','表头行'],['toggleHeaderColumn','表头列']]" :key="name" @mousedown.prevent @click="command(name)">{{ label }}</button></div><label>表题<input :value="editor?.getAttributes('table').caption || ''" @input="command('updateAttributes',['table',{caption:inputValue($event)}])"></label><button @mousedown.prevent @click="editor?.chain().focus().updateAttributes('table',{caption:askText('表题',editor.getAttributes('table').caption??'')??''}).run()">修改表题</button><button @mousedown.prevent @click="editor?.chain().focus().updateAttributes('table',{note:askText('表注',editor.getAttributes('table').note??'')??''}).run()">修改表注</button></details><details open><summary>查找与替换</summary><input v-model="searchText" aria-label="查找文字" placeholder="查找文字"><input v-model="replaceText" aria-label="替换文字" placeholder="替换为"><div class="table-tools"><button @click="findReplace()">查找下一处</button><button @click="findReplace(true)">全部替换</button></div></details><div class="table-tools"><button @mousedown.prevent @click="blockMove(-1)">块上移</button><button @mousedown.prevent @click="blockMove(1)">块下移</button></div></section>
        <section v-if="inspector==='assets'" class="properties"><strong>工程素材</strong><button @click="mediaInput?.click()">导入图音视频</button><select v-model="selectedAssetId" aria-label="素材列表"><option value="">选择素材</option><option v-for="asset in project?.assets" :key="asset.id" :value="asset.id">{{ asset.title||asset.id }}</option></select><template v-if="activeAsset"><label>名称<input v-model="activeAsset.title" @input="markDirty"></label><label>说明<textarea v-model="activeAsset.caption" @input="markDirty"></textarea></label><label>来源类型<input v-model="activeAsset.sourceType" placeholder="自然录音 / 处理结果 / 合成声音" @input="markDirty"></label><label>来源说明<textarea :value="typeof activeAsset.source==='string'?activeAsset.source:JSON.stringify(activeAsset.source??'')" @input="activeAsset.source=inputValue($event);markDirty()"></textarea></label><label>分发范围<select v-model="activeAsset.distribution" @change="activeAsset.git=activeAsset.distribution==='public';markDirty()"><option value="software-only">仅软件分发，排除公开 Git</option><option value="public">可公开内容</option></select></label><small>相对路径：{{ activeAsset.path }}<br>SHA-256：{{ activeAsset.sha256 }}</small><img v-if="activeAsset.kind==='image'" :src="assetUrl(activeAsset)" :alt="activeAsset.alt||''"><audio v-if="activeAsset.kind==='audio'" :src="assetUrl(activeAsset)" controls preload="metadata"></audio><video v-if="activeAsset.kind==='video'" :src="assetUrl(activeAsset)" controls preload="metadata"></video><button @mousedown.prevent @click="insertNode(activeAsset.kind,{assetId:activeAsset.id,caption:activeAsset.caption||''})">插入所选素材</button><details><summary>正文引用位置</summary><p v-for="chapter in snapshot.chapters.filter(c=>JSON.stringify(c.body).includes(activeAsset!.id))" :key="chapter.id"><button @click="selectChapter(chapter.id)">{{ chapter.title }}</button></p></details></template></section>
        <section v-if="inspector==='references'" class="properties"><strong>参考文献</strong><button @click="addReference">新增文献</button><article v-for="reference in project?.references" :key="reference.id" class="reference-card"><label>书目信息<input v-model="reference.label" @input="markDirty"></label><label>来源链接<input v-model="reference.url" @input="markDirty"></label><small>{{ reference.id }}</small><button @mousedown.prevent @click="insertNode('citation',{referenceId:reference.id,label:reference.label})">插入引用</button></article></section>
      </aside>
      <section v-if="preview" class="reading-preview"><header><strong>正式阅读预览</strong><select v-model="previewSource" aria-label="预览内容版本"><option value="live">源稿实时</option><option v-if="generated" value="generated">已生成阅读版</option></select><select v-model="previewWidth" aria-label="预览宽度"><option value="auto">自适应</option><option value="480px">窄栏 480</option><option value="760px">正文 760</option><option value="1024px">宽屏 1024</option></select></header><div class="reader-surface" :style="{width:previewWidth==='auto'?'100%':previewWidth}"><ManualDocument v-if="previewChapter" :chapter="previewChapter" :assets="previewAssets" :references="previewReferences" :asset-resolver="previewAssetUrl" @navigate="navigate" /><p v-else class="muted">新建章节后会显示正式阅读效果。</p></div></section>
    </section>
    <input ref="mediaInput" hidden type="file" accept="image/png,image/jpeg,image/webp,image/gif,audio/*,video/*,.wav,.flac,.mp3,.ogg,.m4a,.mp4,.webm,.mov" @change="mediaPicked"><input ref="importInput" hidden type="file" accept=".gz,.ptbmanual" @change="importProject">
    <div v-if="sourceVisible" class="modal-backdrop"><section class="modal source-modal" role="dialog" aria-modal="true" aria-label="章节结构源码"><header><strong>章节结构源码</strong><button @click="sourceVisible=false">关闭</button></header><p>高级编辑保留稳定 ID。应用前验证节点与链接，未支持内容会明确提示。</p><textarea v-model="sourceDraft" aria-label="章节JSON源码" spellcheck="false"></textarea><footer><button @click="sourceDownload">导出原始章节</button><button class="primary" @click="applySource">验证并应用</button></footer></section></div>
    <div v-if="recoveryVisible" class="modal-backdrop"><section class="modal" role="dialog" aria-modal="true" aria-label="磁盘恢复稿"><header><strong>磁盘恢复稿</strong><button @click="recoveryVisible=false">关闭</button></header><p>恢复稿先加载到编辑界面，正式保存仍进行外部修改检查。</p><div class="recovery-list"><button v-for="item in recoveryItems" :key="item.id" @click="loadRecovery(item.id)">{{ new Date(item.time).toLocaleString('zh-CN') }} · {{ item.chapterCount }} 章<small>{{ item.id }}</small></button><p v-if="!recoveryItems.length">此工程尚无恢复稿。</p></div></section></div>
  </main>
</template>
